using System.Collections.Generic;
using UnityEngine;

namespace PacMan.Game
{
    /// <summary>
    /// Materials and models in Assets/Resources. The materials are generated by the editor menu
    /// Pac-Man > Setup Project; the models by Blender/build_models.py.
    /// </summary>
    public static class Art
    {
        static readonly Dictionary<string, Material> Materials = new Dictionary<string, Material>();

        public static Material Mat(string name)
        {
            if (Materials.TryGetValue(name, out var m) && m != null) return m;
            m = Resources.Load<Material>("Materials/" + name);
            if (m == null)
            {
                Debug.LogWarning($"Material '{name}' is missing. Run the menu Pac-Man > Setup Project.");
                m = new Material(Shader.Find("Universal Render Pipeline/Lit")) { name = name };
            }
            Materials[name] = m;
            return m;
        }

        public static GameObject Model(string name)
        {
            var prefab = Resources.Load<GameObject>("Models/" + name);
            if (prefab == null) Debug.LogError($"Model '{name}' is missing. Run Blender/build_models.py.");
            return prefab;
        }

        /// <summary>Instantiates a model and swaps its imported materials for the project's ones, by name.</summary>
        public static GameObject Spawn(string model, Transform parent)
        {
            var go = Object.Instantiate(Model(model), parent, false);
            go.name = model;
            foreach (var r in go.GetComponentsInChildren<Renderer>(true))
            {
                var mats = r.sharedMaterials;
                for (int i = 0; i < mats.Length; i++)
                    if (mats[i] != null) mats[i] = Mat(mats[i].name.Replace(" (Instance)", ""));
                r.sharedMaterials = mats;
            }
            return go;
        }

        /// <summary>Destroy that also works outside play mode (the editor snapshot tool).</summary>
        public static void Kill(Object o)
        {
            if (Application.isPlaying) Object.Destroy(o);
            else Object.DestroyImmediate(o);
        }

        public static GameObject Primitive(PrimitiveType type, string name, Transform parent, Material mat, bool shadows = true)
        {
            var go = GameObject.CreatePrimitive(type);
            go.name = name;
            Kill(go.GetComponent<Collider>());
            go.transform.SetParent(parent, false);
            var r = go.GetComponent<MeshRenderer>();
            r.sharedMaterial = mat;
            r.shadowCastingMode = shadows ? UnityEngine.Rendering.ShadowCastingMode.On : UnityEngine.Rendering.ShadowCastingMode.Off;
            return go;
        }
    }
}
